typedef struct {
  int *keys;
  int *vals;
  int *order;
  int size;
  int capacity;
} LRUCache;

LRUCache *lRUCacheCreate(int capacity) {
  LRUCache *obj = (LRUCache *)malloc(sizeof(LRUCache));
  obj->keys = (int *)malloc(sizeof(int) * capacity);
  obj->vals = (int *)malloc(sizeof(int) * capacity);
  obj->order = (int *)malloc(sizeof(int) * capacity);
  obj->size = 0;
  obj->capacity = capacity;
  return obj;
}

static void touch(LRUCache *obj, int idx) {
  for (int i = idx; i < obj->size - 1; i++) {
    obj->keys[i] = obj->keys[i + 1];
    obj->vals[i] = obj->vals[i + 1];
    obj->order[i] = obj->order[i + 1];
  }
}

int lRUCacheGet(LRUCache *obj, int key) {
  for (int i = 0; i < obj->size; i++) {
    if (obj->keys[i] == key) {
      int val = obj->vals[i];
      touch(obj, i);
      obj->size--;
      obj->keys[obj->size] = key;
      obj->vals[obj->size] = val;
      obj->size++;
      return val;
    }
  }
  return -1;
}

void lRUCachePut(LRUCache *obj, int key, int value) {
  for (int i = 0; i < obj->size; i++) {
    if (obj->keys[i] == key) {
      touch(obj, i);
      obj->size--;
      break;
    }
  }
  if (obj->size == obj->capacity) {
    touch(obj, 0);
    obj->size--;
  }
  obj->keys[obj->size] = key;
  obj->vals[obj->size] = value;
  obj->size++;
}

class LRUCache {
  int capacity;
  list<pair<int, int>> items;
  unordered_map<int, list<pair<int, int>>::iterator> map;

public:
  LRUCache(int capacity) : capacity(capacity) {}

  int get(int key) {
    auto it = map.find(key);
    if (it == map.end()) return -1;
    items.splice(items.begin(), items, it->second);
    return it->second->second;
  }

  void put(int key, int value) {
    auto it = map.find(key);
    if (it != map.end()) {
      it->second->second = value;
      items.splice(items.begin(), items, it->second);
      return;
    }
    if ((int)items.size() == capacity) {
      int evict = items.back().first;
      items.pop_back();
      map.erase(evict);
    }
    items.push_front({key, value});
    map[key] = items.begin();
  }
};

type entry struct {
	key, value int
}

type LRUCache struct {
	capacity int
	items    *list.List
	index    map[int]*list.Element
}

func Constructor(capacity int) LRUCache {
	return LRUCache{capacity: capacity, items: list.New(), index: map[int]*list.Element{}}
}

func (c *LRUCache) Get(key int) int {
	if el, ok := c.index[key]; ok {
		c.items.MoveToFront(el)
		return el.Value.(*entry).value
	}
	return -1
}

func (c *LRUCache) Put(key int, value int) {
	if el, ok := c.index[key]; ok {
		el.Value.(*entry).value = value
		c.items.MoveToFront(el)
		return
	}
	if c.items.Len() == c.capacity {
		back := c.items.Back()
		c.items.Remove(back)
		delete(c.index, back.Value.(*entry).key)
	}
	el := c.items.PushFront(&entry{key, value})
	c.index[key] = el
}

class LRUCache {
  private int capacity;
  private LinkedHashMap<Integer, Integer> map;

  public LRUCache(int capacity) {
    this.capacity = capacity;
    this.map = new LinkedHashMap<>(capacity, 0.75f, true);
  }

  public int get(int key) {
    return map.getOrDefault(key, -1);
  }

  public void put(int key, int value) {
    map.put(key, value);
    if (map.size() > capacity) {
      Integer eldest = map.keySet().iterator().next();
      map.remove(eldest);
    }
  }
}

class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.map = OrderedDict()

    def get(self, key: int) -> int:
        if key not in self.map:
            return -1
        self.map.move_to_end(key)
        return self.map[key]

    def put(self, key: int, value: int) -> None:
        if key in self.map:
            self.map.move_to_end(key)
        self.map[key] = value
        if len(self.map) > self.capacity:
            self.map.popitem(last=False)

impl LRUCache {
  pub fn new(capacity: i32) -> Self {
    LRUCache {
      capacity: capacity as usize,
      keys: HashMap::new(),
      order: VecDeque::new(),
    }
  }

  pub fn get(&mut self, key: i32) -> i32 {
    if let Some(&v) = self.keys.get(&key) {
      self.touch(key);
      v
    } else {
      -1
    }
  }

  pub fn put(&mut self, key: i32, value: i32) {
    if self.keys.contains_key(&key) {
      self.keys.insert(key, value);
      self.touch(key);
      return;
    }
    if self.keys.len() == self.capacity {
      if let Some(evict) = self.order.pop_back() {
        self.keys.remove(&evict);
      }
    }
    self.keys.insert(key, value);
    self.order.push_front(key);
  }

  fn touch(&mut self, key: i32) {
    self.order.retain(|&k| k != key);
    self.order.push_front(key);
  }
}

class LRUCache {
  private capacity: number;
  private map = new Map<number, number>();

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  get(key: number): number {
    if (!this.map.has(key)) return -1;
    const val = this.map.get(key)!;
    this.map.delete(key);
    this.map.set(key, val);
    return val;
  }

  put(key: number, value: number): void {
    if (this.map.has(key)) this.map.delete(key);
    this.map.set(key, value);
    if (this.map.size > this.capacity) {
      this.map.delete(this.map.keys().next().value as number);
    }
  }
}
